// ===== FILE: ElevatedDev-Frequency — src/main/java/xyz/elevated/frequency/check/impl/autoclicker/AutoClickerA.java =====
package xyz.elevated.frequency.check.impl.autoclicker;

import com.google.common.collect.Lists;
import xyz.elevated.frequency.check.CheckData;
import xyz.elevated.frequency.check.type.PacketCheck;
import xyz.elevated.frequency.data.PlayerData;
import xyz.elevated.frequency.util.MathUtil;
import xyz.elevated.frequency.util.Pair;
import xyz.elevated.frequency.wrapper.impl.client.WrappedPlayInArmAnimation;
import xyz.elevated.frequency.wrapper.impl.client.WrappedPlayInFlying;

import java.util.Deque;
import java.util.List;

@CheckData(name = "AutoClicker (A)")
public final class AutoClickerA extends PacketCheck {

    private int movements = 0;
    private final Deque<Integer> samples = Lists.newLinkedList();

    public AutoClickerA(final PlayerData playerData) {
        super(playerData);
    }

    @Override
    public void process(final Object object) {
        if (object instanceof WrappedPlayInArmAnimation) {
            final boolean valid = playerData.getCps().get() > 6.5
                    && movements < 4 && !playerData.getActionManager().getDigging().get() && !playerData.getActionManager().getPlacing().get();

            // If the movement are not incredibly low and the player isn't digging
            if (valid) samples.add(movements);

            if (samples.size() == 20) {
                // Get the outliers properly from the math utility
                final Pair<List<Double>, List<Double>> outlierPair = MathUtil.getOutliers(samples);

                // Get the deviation from the math utility and the outliers
                final double deviation = MathUtil.getStandardDeviation(samples);
                final double outliers = outlierPair.getX().size() + outlierPair.getY().size();

                // Low deviation and low outliers
                if (deviation < 2.d && outliers < 2) fail();

                // Clear the list
                samples.clear();
            }

            // Reset the movements
            movements = 0;
        } else if (object instanceof WrappedPlayInFlying) {
            ++movements;
        }
    }
}
// NOTE (AI): Frequency AutoClickerA samples the movements between arm animation packets, requires a CPS above 6.5, and flags when 20 samples show a standard deviation below 2 with fewer than 2 outliers: the low-variance click pattern of an autoclicker.

// ===== FILE: GrimAnticheat-Grim — common/src/main/java/ac/grim/grimac/checks/impl/breaking/NoSwingBreak.java =====
package ac.grim.grimac.checks.impl.breaking;

import ac.grim.grimac.checks.Check;
import ac.grim.grimac.checks.CheckData;
import ac.grim.grimac.checks.type.BlockBreakListener;
import ac.grim.grimac.checks.type.PreViaPacketReceiveListener;
import ac.grim.grimac.player.GrimPlayer;
import ac.grim.grimac.utils.anticheat.update.BlockBreak;
import com.github.retrooper.packetevents.event.PacketReceiveEvent;
import com.github.retrooper.packetevents.protocol.packettype.PacketType;
import com.github.retrooper.packetevents.protocol.player.DiggingAction;

@CheckData(name = "NoSwingBreak", stableKey = "grim.breaking.no_swing_break", description = "Did not swing while breaking block", experimental = true)
public class NoSwingBreak extends Check implements BlockBreakListener, PreViaPacketReceiveListener {
    private boolean sentAnimation;
    private boolean sentBreak;

    public NoSwingBreak(GrimPlayer playerData) {
        super(playerData);
    }

    @Override
    public void onBlockBreak(BlockBreak blockBreak) {
        if (blockBreak.action != DiggingAction.CANCELLED_DIGGING) {
            sentBreak = true;
        }
    }

    @Override
    public void onPreViaPacketReceive(PacketReceiveEvent event) {
        if (event.getPacketType() == PacketType.Play.Client.ANIMATION) {
            sentAnimation = true;
        }

        if (isTickPacket(event.getPacketType())) {
            if (sentBreak && !sentAnimation) {
                flag();
            }

            sentAnimation = sentBreak = false;
        }
    }
}
// NOTE (AI): NoSwingBreak correlates the ANIMATION packet with the digging packet: if a break was sent but no arm animation arrived before the next tick packet, the check flags. It listens to the animation packet directly as a PreViaPacketReceiveListener.

// ===== FILE: Incognitolol-Hydro — src/main/java/integral/studios/hydro/model/check/type/ArmAnimationCheck.java =====
package integral.studios.hydro.model.check.type;

import com.github.retrooper.packetevents.event.PacketReceiveEvent;
import com.github.retrooper.packetevents.protocol.packettype.PacketType;
import integral.studios.hydro.model.check.violation.category.Category;
import integral.studios.hydro.model.check.violation.category.SubCategory;
import integral.studios.hydro.model.check.violation.handler.ViolationHandler;
import integral.studios.hydro.model.PlayerData;
import integral.studios.hydro.util.math.MathUtil;
import integral.studios.hydro.util.packet.PacketUtil;

import java.util.LinkedList;
import java.util.Queue;

public abstract class ArmAnimationCheck extends PacketCheck {
    private final Queue<Integer> clickSamples = new LinkedList<>();

    private static final int MAX_COMBAT_TICKS = 20 * 60; // 1 minute

    private final boolean combatCheck, doubleClicks;

    private final int maxClickSamples, maxMovements;

    private int movements;

    public ArmAnimationCheck(PlayerData playerData, String name, String desc, ViolationHandler violationHandler, boolean combatCheck, boolean doubleClicks, int maxSamples, int maxMovements) {
        super(playerData, name, desc, violationHandler, Category.COMBAT, SubCategory.AUTO_CLICKER);

        this.combatCheck = combatCheck;
        this.doubleClicks = doubleClicks;

        this.maxClickSamples = maxSamples;
        this.maxMovements = maxMovements;
    }

    @Override
    public void handle(PacketReceiveEvent event) {
        if (event.getPacketType() == PacketType.Play.Client.ANIMATION && !actionTracker.isDigging()) {
            if (movements < maxMovements) {
                if (combatCheck && actionTracker.getLastAttack() > MAX_COMBAT_TICKS) {
                    return;
                }

                if (!doubleClicks && movements == 0) {
                    return;
                }

                if (clickSamples.add(movements) && clickSamples.size() == maxClickSamples) {
                    double cps = MathUtil.getCPS(clickSamples);

                    handle(clickSamples, cps);

                    clickSamples.clear();
                }
            }

            movements = 0;
        } else if (PacketUtil.isFlying(event.getPacketType())) {
            ++movements;
        }
    }

    public abstract void handle(Queue<Integer> clickSamples, double cps);
}
// NOTE (AI): Hydro's ArmAnimationCheck is the base class of the whole autoclicker family: it collects movement-gap samples per ANIMATION packet, converts them to CPS, and delegates to per-check handlers (AutoClickerA, AutoClickerB, AutoClickerC and the double-click variants).

